"""Finance dashboard queries (moved over from the old billing monolith)."""

from datetime import date, datetime, time, timedelta

from .clock import ensure_utc


def day_bounds(day: date) -> tuple[datetime, datetime]:
    start = datetime.combine(day, time.min)
    return start, start + timedelta(days=1)


def total_amount(payments) -> float:
    return round(sum(float(p.amount) for p in payments), 2)


def payments_between(payments, start, end):
    """Payments created in [start, end), oldest first.

    Boundaries are normalized to UTC so that aware datetimes in different
    timezones compare correctly. Payments without a ``created_at`` are
    excluded, as they cannot fall inside the window.
    """
    start = ensure_utc(start)
    end = ensure_utc(end)
    selected = [
        p for p in payments
        if p.created_at is not None and start <= ensure_utc(p.created_at) < end
    ]
    return sorted(selected, key=lambda p: ensure_utc(p.created_at))
EOF
